452:   const desertScrap = [];
453:   for (let i = 0; i < 26; i++) {
454:     let x, y, ok = false;
455:     for (let t = 0; t < 40 && !ok; t++) {
456:       x = 220 + rng() * (WORLD.w - 440);
457:       y = 220 + rng() * (WORLD.h - 440);
458:       ok = dist(x, y, OUTPOST.x, OUTPOST.y) > 360;
459:       if (ok) for (const s of SITE_DEFS) if (dist(x, y, s.x, s.y) < s.w * 0.68) { ok = false; break; }
460:     }
461:     if (ok) desertScrap.push({ id: `desert-${i}`, type: 'scrap', x, y, amount: 1 + Math.floor(rng() * 3) });
462:   }
463:   const ruins = SITE_DEFS.map(buildRuin);
464:   const stars = [];
465:   for (let i = 0; i < 170; i++) {
466:     stars.push({ x: rng(), y: rng() * 0.6, s: rng() * 1.5 + 0.3, tw: rng() * TAU });
467:   }
468:   world = { dunes, rocks, shrubs, bones, debris, desertScrap, ruins, stars, mist: 0 };
469: }
