516: function capacity() { return 18 + state.upgrades.pack * 8; }
517: function weight() { return state.scrap + state.relics * 2 + state.cores.length * 2; }
518: function speed() {
519:   const base = 144 * (1 + state.upgrades.boots * 0.15);
520:   return state.player.sprint ? base * 1.46 : base;
