522: function scanRadius() { return 860 * (1 + state.upgrades.scanner * 0.45); }
523: function scanCooldownMax() { return Math.max(2.8, 6.2 - state.upgrades.scanner * 2); }
524: function shields() { return state.upgrades.canteen > 0 ? 0.76 : 1; }
