527: function saveGame(silent = true) {
528:   if (!state || mode !== 'playing') return;
529:   try {
530:     const data = {
531:       version: 1,
532:       player: { ...state.player },
533:       water: state.water, food: state.food, health: state.health,
534:       credits: state.credits, scrap: state.scrap, relics: state.relics,
535:       cores: state.cores.slice(), upgrades: { ...state.upgrades },
536:       clock: state.clock, day: state.day,
537:       weather: { type: state.weather.type, timer: state.weather.timer },
538:       nodes: { ...state.nodes }, discovered: { ...state.discovered },
539:       stats: { ...state.stats }, elapsed: state.elapsed, flags: { ...state.flags }
540:     };
541:     localStorage.setItem(SAVE_KEY, JSON.stringify(data));
542:   } catch (e) { /* storage may be unavailable */ }
543: }
