549: function loadGame() {
550:   try {
551:     const raw = localStorage.getItem(SAVE_KEY);
552:     if (!raw) return false;
553:     const data = JSON.parse(raw);
554:     if (!data || data.version !== 1) return false;
555:     state = freshState();
556:     Object.assign(state.player, data.player || {});
557:     state.water = data.water ?? 50;
558:     state.food = data.food ?? 50;
559:     state.health = data.health ?? 100;
560:     state.credits = data.credits ?? 0;
561:     state.scrap = data.scrap ?? 0;
562:     state.relics = data.relics ?? 0;
563:     state.cores = Array.isArray(data.cores) ? data.cores : [];
564:     Object.assign(state.upgrades, data.upgrades || {});
565:     state.clock = data.clock ?? 440;
566:     state.day = data.day ?? 1;
567:     if (data.weather) state.weather.type = data.weather.type;
568:     if (data.weather) state.weather.timer = data.weather.timer;
569:     if (data.nodes) state.nodes = { ...state.nodes, ...data.nodes };
570:     state.discovered = data.discovered || {};
571:     state.stats = { ...state.stats, ...(data.stats || {}) };
572:     state.elapsed = data.elapsed || 0;
573:     state.flags = { ...state.flags, ...(data.flags || {}) };
574:     camera.x = state.player.x; camera.y = state.player.y;
575:     return true;
576:   } catch (e) { return false; }
577: }
