887: function sizeMapCanvas() {
888:   const c = document.getElementById('mapCanvas');
889:   if (!c) return;
890:   const rect = c.getBoundingClientRect();
891:   if (!rect.width) return;
892:   const d = Math.min(2, devicePixelRatio || 1);
893:   c.width = Math.round(rect.width * d);
894:   c.height = Math.round(rect.width * d);
895: }
