897: function drawMap() {
898:   const c = document.getElementById('mapCanvas');
899:   if (!c) return;
900:   sizeMapCanvas();
901:   const g = c.getContext('2d');
902:   const w = c.width, h = c.height;
903:   g.clearRect(0, 0, w, h);
904:   const pad = w * 0.065;
905:   const scale = (w - pad * 2) / WORLD.w;
906:   const X = v => pad + v * scale;
907:   const Y = v => pad + v * scale;
908: 
909:   g.fillStyle = '#1b140e';
910:   g.fillRect(0, 0, w, h);
911: 
912:   // contour lines
913:   g.strokeStyle = 'rgba(218,178,118,.07)';
914:   g.lineWidth = Math.max(1, w / 900);
915:   for (let i = 0; i < 24; i++) {
916:     g.beginPath();
917:     const y = pad + (i / 24) * (h - pad * 2) + Math.sin(i) * 6;
918:     g.moveTo(pad, y);
919:     for (let x = 0; x <= w; x += w / 20) {
920:       g.lineTo(x, y + Math.sin(x * 0.028 + i) * 8 + Math.cos(x * 0.011 - i) * 4);
921:     }
922:     g.stroke();
923:   }
924:   // grid
925:   g.strokeStyle = 'rgba(218,178,118,.045)';
926:   for (let i = 1; i < 8; i++) {
927:     const p = pad + (i / 8) * (w - pad * 2);
928:     g.beginPath(); g.moveTo(p, pad); g.lineTo(p, h - pad); g.stroke();
929:     g.beginPath(); g.moveTo(pad, p); g.lineTo(w - pad, p); g.stroke();
930:   }
931:   g.strokeStyle = 'rgba(229,191,132,.22)';
932:   g.lineWidth = 1.5;
933:   g.strokeRect(pad, pad, w - pad * 2, h - pad * 2);
