312: function buildRuin(def) {
313:   const rng = mulberry32(def.seed * 997 + 13);
314:   const hw = def.w / 2, hh = def.h / 2, t = 14;
315:   const walls = [];
316:   const addWall = (x, y, w, h) => walls.push({ x: def.x + x, y: def.y + y, w, h });
317:   const addLocal = (x, y, w, h) => addWall(x, y, w, h);
318: 
319:   // Outer shell with collapsed gaps and one broad entrance.
320:   addLocal(-hw, -hh, def.w * 0.61, t);
321:   addLocal(-hw + def.w * 0.72, -hh, def.w * 0.28, t);
322:   addLocal(-hw, hh - t, def.w * 0.42, t);
323:   addLocal(-hw + def.w * 0.59, hh - t, def.w * 0.41, t);
324:   addLocal(-hw, -hh + t, t, def.h * 0.52);
325:   addLocal(-hw, hh * 0.66, t, hh * 0.34 - t);
326:   addLocal(hw - t, -hh + t, t, def.h * 0.31);
327:   addLocal(hw - t, -hh + def.h * 0.44, t, def.h * 0.56 - t);
328: 
329:   // Inner rooms, intentionally incomplete.
330:   addLocal(-def.w * 0.22, -hh + 28, t, def.h * 0.25);
331:   addLocal(-def.w * 0.22, hh * 0.32, t, hh * 0.68 - t - 24);
332:   addLocal(-hw + 28, hh * 0.12, def.w * 0.22, t);
333:   addLocal(hw * 0.20, hh * 0.12, def.w * 0.30, t);
334: 
335:   // Broken columns are solid and also drawn as circles.
336:   const pillars = [];
337:   const pillarSpots = [[-hw + 42, -hh + 42], [hw - 46, -hh + 46], [hw - 54, hh - 48], [-hw + 48, hh - 46]];
338:   for (const [px, py] of pillarSpots) {
339:     if (rng() > 0.22) pillars.push({ x: def.x + px, y: def.y + py, r: 10 + rng() * 4 });
340:   }
341: 
342:   const floor = { x: def.x - hw, y: def.y - hh, w: def.w, h: def.h };
343:   const cracks = [];
344:   for (let i = 0; i < 13; i++) {
345:     const sx = def.x + (rng() - 0.5) * def.w * 0.9;
346:     const sy = def.y + (rng() - 0.5) * def.h * 0.82;
347:     const pts = [[0, 0]];
348:     let ang = rng() * TAU;
349:     for (let j = 0; j < 4; j++) {
350:       ang += (rng() - 0.5) * 1.4;
351:       const l = 8 + rng() * 20;
352:       const last = pts[pts.length - 1];
353:       pts.push([last[0] + Math.cos(ang) * l, last[1] + Math.sin(ang) * l]);
354:     }
355:     cracks.push({ x: sx, y: sy, pts });
356:   }
357: 
358:   const rubble = [];
359:   for (let i = 0; i < 28; i++) {
360:     let rx, ry, ok = false;
361:     for (let k = 0; k < 30 && !ok; k++) {
362:       rx = def.x + (rng() - 0.5) * (def.w + 80);
363:       ry = def.y + (rng() - 0.5) * (def.h + 70);
364:       ok = true;
365:       for (const w of walls) if (inWall(rx, ry, w, 10)) { ok = false; break; }
366:     }
367:     if (ok) rubble.push({ x: rx, y: ry, s: 2 + rng() * 7, a: rng() * TAU, shade: rng() });
368:   }
369: 
370:   const nodeDefs = [];
371:   const nodes = [];
372:   const count = def.tier + 3;
373:   const corePos = { x: def.x + def.w * 0.15, y: def.y - def.h * 0.18 };
374:   for (let i = 0; i < count; i++) {
375:     let nx, ny, ok = false;
376:     for (let tries = 0; tries < 80 && !ok; tries++) {
377:       nx = def.x + (rng() - 0.5) * (def.w - 76);
378:       ny = def.y + (rng() - 0.5) * (def.h - 76);
379:       ok = true;
380:       for (const w of walls) if (inWall(nx, ny, w, 25)) { ok = false; break; }
381:       if (ok) for (const p of pillars) if (dist(nx, ny, p.x, p.y) < 30) { ok = false; break; }
382:       if (ok) for (const n of nodes) if (dist(nx, ny, n.x, n.y) < 42) { ok = false; break; }
383:       if (ok && def.core && dist(nx, ny, corePos.x, corePos.y) < 65) ok = false;
384:     }
385:     if (ok) {
386:       const node = { id: `${def.id}-scrap-${i}`, type: 'scrap', x: nx, y: ny, amount: 2 + Math.floor(rng() * 3) };
387:       nodes.push(node); nodeDefs.push(node);
388:     }
389:   }
390:   // one sealed cache per ruin
391:   let cx, cy, ok = false;
392:   for (let tries = 0; tries < 80 && !ok; tries++) {
393:     cx = def.x + (rng() - 0.5) * (def.w - 84);
394:     cy = def.y + (rng() - 0.5) * (def.h - 84);
395:     ok = true;
396:     for (const w of walls) if (inWall(cx, cy, w, 26)) { ok = false; break; }
397:     for (const n of nodes) if (dist(cx, cy, n.x, n.y) < 40) { ok = false; break; }
398:     if (ok && def.core && dist(cx, cy, corePos.x, corePos.y) < 72) ok = false;
399:   }
400:   if (ok) {
401:     const node = { id: `${def.id}-cache`, type: 'cache', x: cx, y: cy, amount: 1 };
402:     nodes.push(node); nodeDefs.push(node);
403:   }
404:   if (def.core) {
405:     const node = { id: `${def.id}-core`, type: 'core', x: corePos.x, y: corePos.y, amount: 1, site: def.id };
406:     nodes.push(node); nodeDefs.push(node);
407:   }
