2499: function drawEffects() {
2500:   for (const e of effects) {
2501:     const k = e.age / e.duration;
2502:     if (e.type === 'scan') {
2503:       const r = e.max * (0.12 + k * 0.88);
2504:       ctx.save();
2505:       ctx.strokeStyle = `rgba(${e.color},${(1 - k) * 0.55})`;
2506:       ctx.lineWidth = 2 + (1 - k) * 2;
2507:       ctx.beginPath(); ctx.arc(e.x, e.y, r, 0, TAU); ctx.stroke();
2508:       ctx.strokeStyle = `rgba(${e.color},${(1 - k) * 0.18})`;
2509:       ctx.lineWidth = 8;
2510:       ctx.beginPath(); ctx.arc(e.x, e.y, r, 0, TAU); ctx.stroke();
2511:       ctx.restore();
2512:     }
2513:   }
2514:   for (const pt of particles) {
2515:     const k = pt.life / pt.max;
2516:     if (pt.type === 'dust') {
2517:       ctx.fillStyle = `rgba(228,194,145,${k * 0.28})`;
2518:       ctx.beginPath(); ctx.arc(pt.x, pt.y, pt.size * (1.4 - k * 0.4), 0, TAU); ctx.fill();
2519:     } else {
2520:       ctx.save();
2521:       ctx.translate(pt.x, pt.y); ctx.rotate(pt.a);
2522:       ctx.fillStyle = `rgba(93,63,39,${k * 0.22})`;
2523:       ctx.fillRect(-2.4, -1, 4.8, 2);
2524:       ctx.restore();
2525:     }
2526:   }
2527:   // ambient blowing sand
2528:   const t = state.elapsed;
2529:   for (let i = 0; i < 26; i++) {
2530:     const seed = hash2(i, 3.3);
2531:     const x = (seed * WORLD.w + t * (18 + seed * 32)) % WORLD.w;
2532:     const y = ((hash2(i, 8.7) * WORLD.h) + Math.sin(t * 0.3 + i) * 80) % WORLD.h;
2533:     if (dist(x, y, state.player.x, state.player.y) > 850) continue;
2534:     ctx.strokeStyle = `rgba(247,224,185,${0.08 + seed * 0.06})`;
2535:     ctx.lineWidth = 1;
2536:     ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 14 + seed * 12, y - 2); ctx.stroke();
2537:   }
2538: }
