2540: function drawLighting() {
2541:   const sun = getSunAmount();
2542:   const night = clamp(1 - sun * 2.0, 0, 1);
2543:   const dusk = clamp(1 - Math.abs(sun - 0.13) * 4.4, 0, 1) * 0.34;
2544:   ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
2545:   if (night > 0.015) {
2546:     ctx.fillStyle = `rgba(9,15,27,${night * 0.58})`;
2547:     ctx.fillRect(0, 0, view.w, view.h);
2548:   }
2549:   if (dusk > 0.01) {
2550:     ctx.fillStyle = `rgba(132,58,28,${dusk})`;
2551:     ctx.fillRect(0, 0, view.w, view.h);
2552:   }
2553:   // storm veil
2554:   const wi = state.weather.intensity;
2555:   if (wi > 0.01) {
2556:     ctx.fillStyle = `rgba(167,121,74,${wi * 0.17})`;
2557:     ctx.fillRect(0, 0, view.w, view.h);
2558:     ctx.save();
2559:     ctx.globalAlpha = wi * 0.5;
2560:     ctx.strokeStyle = 'rgba(236,202,152,.45)';
2561:     ctx.lineWidth = 1;
2562:     const t = state.elapsed;
2563:     for (let i = 0; i < 95; i++) {
2564:       const seed = hash2(i, 9.1);
2565:       const spd = 220 + seed * 420;
2566:       const x = ((seed * view.w * 1.5 + t * spd) % (view.w + 260)) - 130;
2567:       const y = ((hash2(i, 4.7) * view.h + Math.sin(t * 0.8 + i) * 25 + t * 30 * (0.4 + seed)) % (view.h + 80)) - 40;
2568:       ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 22 - seed * 34, y + 3 + seed * 3); ctx.stroke();
2569:     }
2570:     ctx.restore();
2571:   }
2572: 
2573:   // Lights (additive, world space)
2574:   ctx.save();
2575:   screenTransform(0, 0);
2576:   ctx.globalCompositeOperation = 'lighter';
2577:   const p = state.player;
2578:   const playerGlow = 0.12 + night * 0.72;
2579:   if (playerGlow > 0.13) {
2580:     const gr = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, 125);
2581:     gr.addColorStop(0, `rgba(252,187,103,${0.1 + night * 0.14})`);
2582:     gr.addColorStop(0.4, `rgba(224,142,68,${0.05 + night * 0.07})`);
2583:     gr.addColorStop(1, 'rgba(180,90,40,0)');
2584:     ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(p.x, p.y, 125, 0, TAU); ctx.fill();
2585:   }
2586:   // outpost firelight
2587:   const dOut = dist(p.x, p.y, OUTPOST.x, OUTPOST.y);
2588:   if (dOut < 1050) {
2589:     const fx = OUTPOST.x - 14, fy = OUTPOST.y + 38;
2590:     const flick = 0.9 + Math.sin(state.elapsed * 8) * 0.08;
2591:     const gr = ctx.createRadialGradient(fx, fy, 0, fx, fy, 155);
2592:     gr.addColorStop(0, `rgba(243,161,74,${0.18 * flick})`);
2593:     gr.addColorStop(0.4, `rgba(207,113,50,${0.07 * flick})`);
2594:     gr.addColorStop(1, 'rgba(180,80,30,0)');
2595:     ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(fx, fy, 155, 0, TAU); ctx.fill();
2596:     // string lights
2597:     for (let i = 0; i < 12; i++) {
2598:       const a = i / 12 * TAU;
2599:       const x = OUTPOST.x + Math.cos(a) * 110, y = OUTPOST.y + Math.sin(a) * 84;
2600:       ctx.fillStyle = `rgba(247,193,103,${0.12 + night * 0.22})`;
2601:       ctx.beginPath(); ctx.arc(x, y, 8, 0, TAU); ctx.fill();
2602:     }
2603:   }
2604:   // cores
2605:   for (const r of world.ruins) {
2606:     if (!r.core || state.cores.includes(r.id)) continue;
2607:     if (dist(p.x, p.y, r.x, r.y) > 900) continue;
2608:     const pulse = 0.8 + Math.sin(state.elapsed * 2 + r.seed) * 0.2;
2609:     const gr = ctx.createRadialGradient(r.corePos.x, r.corePos.y - 16, 0, r.corePos.x, r.corePos.y - 16, 85);
2610:     gr.addColorStop(0, `rgba(138,244,224,${0.19 * pulse})`);
2611:     gr.addColorStop(1, 'rgba(80,190,175,0)');
2612:     ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(r.corePos.x, r.corePos.y - 16, 85, 0, TAU); ctx.fill();
2613:   }
2614:   // relay beam
2615:   if (state.flags.relay) {
2616:     const x = RELAY.x, y = RELAY.y - 78;
2617:     const pulse = 0.7 + Math.sin(state.elapsed * 3) * 0.3;
2618:     const gr = ctx.createRadialGradient(x, y, 0, x, y, 200);
2619:     gr.addColorStop(0, `rgba(143,255,233,${0.24 * pulse})`);
2620:     gr.addColorStop(0.5, `rgba(94,220,199,${0.08 * pulse})`);
2621:     gr.addColorStop(1, 'rgba(70,180,165,0)');
2622:     ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(x, y, 200, 0, TAU); ctx.fill();
2623:     ctx.strokeStyle = `rgba(150,255,236,${0.09 * pulse})`;
2624:     ctx.lineWidth = 20;
2625:     ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y - 900); ctx.stroke();
2626:     ctx.strokeStyle = `rgba(210,255,247,${0.12 * pulse})`;
2627:     ctx.lineWidth = 3;
2628:     ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y - 900); ctx.stroke();
2629:   }
2630:   ctx.restore();
2631: 
2632:   // subtle screen bloom around player when very dark
2633:   if (night > 0.35) {
2634:     ctx.save();
2635:     ctx.globalAlpha = 0.13 * night;
2636:     const g2 = ctx.createRadialGradient(view.w / 2, view.h / 2, 10, view.w / 2, view.h / 2, Math.max(view.w, view.h) * 0.6);
2637:     g2.addColorStop(0, 'rgba(255,203,128,.5)');
2638:     g2.addColorStop(1, 'rgba(255,180,90,0)');
2639:     ctx.fillStyle = g2; ctx.fillRect(0, 0, view.w, view.h);
2640:     ctx.restore();
2641:   }
2642: }
