2802: function drawMesaLayer(w, h, yf, color, alpha, phase) {
2803:   ctx.save();
2804:   ctx.globalAlpha = alpha;
2805:   ctx.fillStyle = color;
2806:   ctx.beginPath();
2807:   const baseY = h * yf;
2808:   ctx.moveTo(0, baseY + 40);
2809:   let x = 0;
2810:   let i = 0;
2811:   while (x < w) {
2812:     const step = 60 + hash2(i, phase) * 130;
2813:     const peak = 14 + hash2(i + 9, phase) * 54;
2814:     ctx.lineTo(x + step * 0.24, baseY - peak * 0.2);
2815:     ctx.lineTo(x + step * 0.42, baseY - peak);
2816:     ctx.lineTo(x + step * 0.55, baseY - peak + 5);
2817:     ctx.lineTo(x + step * 0.58, baseY - peak * 0.55);
2818:     ctx.lineTo(x + step * 0.76, baseY - peak * 0.55);
2819:     ctx.lineTo(x + step, baseY + 10);
2820:     x += step; i++;
2821:   }
2822:   ctx.lineTo(w, h * 0.85);
2823:   ctx.lineTo(0, h * 0.85);
2824:   ctx.closePath();
2825:   ctx.fill();
2826:   ctx.restore();
2827: }
