1872:   ctx.beginPath();
1873:   roundRectPath(ctx, r.floor.x + 4, r.floor.y + 4, r.floor.w - 8, r.floor.h - 8, 3);
1874:   ctx.fill();
1875:   // broken floor patches
1876:   const rng = mulberry32(r.seed * 771);
1877:   ctx.globalAlpha = 0.22;
1878:   for (let i = 0; i < 40; i++) {
1879:     const x = r.floor.x + 12 + rng() * (r.floor.w - 24);
1880:     const y = r.floor.y + 12 + rng() * (r.floor.h - 24);
1881:     ctx.fillStyle = rng() > 0.5 ? '#b69568' : '#584331';
1882:     ctx.fillRect(x, y, 3 + rng() * 13, 2 + rng() * 5);
1883:   }
1884:   ctx.globalAlpha = 1;
1885: 
1886:   // interior warm glow from core
1887:   if (r.core && !state.cores.includes(r.id)) {
1888:     const pulse = 0.65 + Math.sin(state.elapsed * 2 + r.seed) * 0.16;
1889:     const gr = ctx.createRadialGradient(r.corePos.x, r.corePos.y, 2, r.corePos.x, r.corePos.y, 110);
1890:     gr.addColorStop(0, `rgba(108,221,205,${0.31 * pulse})`);
1891:     gr.addColorStop(0.4, `rgba(108,190,180,${0.09 * pulse})`);
1892:     gr.addColorStop(1, 'rgba(70,140,132,0)');
1893:     ctx.fillStyle = gr;
1894:     ctx.fillRect(r.floor.x, r.floor.y, r.floor.w, r.floor.h);
1895:   }
