1897:   // cracks
1898:   ctx.strokeStyle = 'rgba(38,28,20,.35)';
1899:   ctx.lineWidth = 1;
1900:   for (const c of r.cracks) {
1901:     ctx.beginPath();
1902:     ctx.moveTo(c.x, c.y);
1903:     for (const pt of c.pts.slice(1)) ctx.lineTo(c.x + pt[0], c.y + pt[1]);
1904:     ctx.stroke();
1905:   }
1906: 
1907:   // low remnants / pipes
1908:   ctx.strokeStyle = 'rgba(201,162,112,.22)';
1909:   ctx.lineWidth = 2.2;
1910:   ctx.beginPath();
1911:   ctx.moveTo(r.floor.x + r.floor.w * 0.6, r.floor.y + 8);
1912:   ctx.lineTo(r.floor.x + r.floor.w * 0.6, r.floor.y + r.floor.h * 0.25);
1913:   ctx.lineTo(r.floor.x + r.floor.w * 0.78, r.floor.y + r.floor.h * 0.25);
1914:   ctx.stroke();
1915: 
1916:   // walls: dark shadow and stone top
1917:   for (const w of r.walls) {
1918:     roundRect(ctx, w.x + 8, w.y + 10, w.w, w.h, 3, 'rgba(38,27,18,.36)');
1919:   }
1920:   for (const w of r.walls) {
1921:     roundRect(ctx, w.x, w.y, w.w, w.h, 2, '#796047');
1922:     roundRect(ctx, w.x, w.y, w.w, Math.max(2, w.h * 0.35), Math.min(4, w.h * 0.45), 'rgba(205,175,130,.5)');
1923:     ctx.fillStyle = 'rgba(44,31,20,.3)';
1924:     for (let i = 0; i < w.w; i += 22) {
1925:       if (hash2(w.x + i, w.y) > 0.6) ctx.fillRect(w.x + i, w.y + w.h - 3, 6, 3);
1926:     }
1927:   }
1928: 
1929:   // pillars
1930:   for (const p of r.pillars) {
1931:     ctx.fillStyle = 'rgba(40,29,20,.32)';
1932:     ctx.beginPath(); ctx.ellipse(p.x + 7, p.y + 9, p.r * 1.1, p.r * 0.7, 0.2, 0, TAU); ctx.fill();
1933:     ctx.fillStyle = '#8e7355';
1934:     ctx.beginPath(); ctx.ellipse(p.x, p.y, p.r, p.r * 0.82, 0, 0, TAU); ctx.fill();
1935:     ctx.fillStyle = 'rgba(219,187,144,.3)';
1936:     ctx.beginPath(); ctx.ellipse(p.x - 2, p.y - 2, p.r * 0.6, p.r * 0.4, 0, 0, TAU); ctx.fill();
1937:   }
