1939:   // rubble
1940:   for (const q of r.rubble) {
1941:     ctx.save(); ctx.translate(q.x, q.y); ctx.rotate(q.a);
1942:     ctx.fillStyle = q.shade > 0.5 ? 'rgba(56,41,27,.55)' : 'rgba(132,100,67,.62)';
1943:     ctx.fillRect(-q.s / 2, -q.s / 3, q.s, q.s * 0.66);
1944:     ctx.restore();
1945:   }
1946: 
1947:   // core pedestal
1948:   if (r.core) {
1949:     const active = !state.cores.includes(r.id);
1950:     const cx = r.corePos.x, cy = r.corePos.y;
1951:     ctx.fillStyle = 'rgba(39,29,21,.42)';
1952:     ctx.beginPath(); ctx.ellipse(cx + 6, cy + 8, 22, 11, 0, 0, TAU); ctx.fill();
1953:     ctx.fillStyle = '#6e5c46';
