2047: function roundRectPath(g, x, y, w, h, r) {
2048:   r = Math.min(r, w / 2, h / 2);
2049:   g.moveTo(x + r, y);
2050:   g.arcTo(x + w, y, x + w, y + h, r);
2051:   g.arcTo(x + w, y + h, x, y + h, r);
2052:   g.arcTo(x, y + h, x, y, r);
2053:   g.arcTo(x, y, x + w, y, r);
2054:   g.closePath();
2055: }
