286:     const a = rnd() * 0.08;
287:     g.fillStyle = rnd() > 0.55 ? `rgba(255,236,200,${a})` : `rgba(95,64,38,${a * 0.8})`;
288:     g.fillRect(x, y, 1 + rnd() * 2, 1);
289:   }
290:   for (let i = 0; i < 12; i++) {
291:     g.strokeStyle = `rgba(105,72,42,${0.025 + rnd() * 0.03})`;
292:     g.lineWidth = 1;
293:     g.beginPath();
294:     const y = rnd() * 256;
295:     g.moveTo(-20, y);
296:     g.bezierCurveTo(70, y - 12, 150, y + 14, 280, y - 4);
297:     g.stroke();
298:   }
299:   terrainPattern = ctx.createPattern(tile, 'repeat');
300: }
