1812: function drawScatter(list, left, top, right, bottom) {
1813:   for (const o of list) {
1814:     if (o.x < left || o.x > right || o.y < top || o.y > bottom) continue;
1815:     ctx.save();
1816:     ctx.translate(o.x, o.y);
1817:     if (o.s > 4.8) {
1818:       ctx.fillStyle = 'rgba(78,52,33,.17)';
1819:       ctx.beginPath(); ctx.ellipse(3, 4, o.s * 1.1, o.s * 0.5, 0.2, 0, TAU); ctx.fill();
1820:     }
1821:     if (o.kind !== undefined && o.s > 3) {
1822:       // bone or debris variation
1823:       if (o.kind < 0.45) {
1824:         ctx.strokeStyle = 'rgba(237,219,187,.5)';
1825:         ctx.lineWidth = 1.5;
1826:         ctx.beginPath(); ctx.moveTo(-o.s, 0); ctx.lineTo(o.s, 0); ctx.stroke();
1827:         ctx.beginPath(); ctx.arc(-o.s, 0, 1.7, 0, TAU); ctx.arc(o.s, 0, 1.7, 0, TAU); ctx.stroke();
1828:       } else {
1829:         ctx.fillStyle = 'rgba(91,65,41,.42)';
1830:         ctx.rotate(o.a);
1831:         ctx.fillRect(-o.s * 0.8, -1, o.s * 1.6, 2);
1832:       }
1833:     } else if (o.a !== undefined && list === world.shrubs) {
1834:       ctx.strokeStyle = 'rgba(98,74,42,.6)';
1835:       ctx.lineWidth = 0.9;
1836:       for (let i = 0; i < 5; i++) {
1837:         const ang = -1.2 + i * 0.45;
1838:         ctx.beginPath(); ctx.moveTo(0, 2); ctx.quadraticCurveTo(Math.cos(ang) * o.s * 0.5, -o.s * 0.45, Math.cos(ang) * o.s, -o.s * 0.7); ctx.stroke();
1839:       }
1840:     } else if (o.tone !== undefined) {
1841:       ctx.fillStyle = o.tone > 0.5 ? 'rgba(86,58,36,.38)' : 'rgba(118,83,49,.42)';
1842:       ctx.rotate(o.a);
1843:       ctx.fillRect(-o.s * 0.65, -o.s * 0.32, o.s * 1.3, o.s * 0.64);
1844:     } else {
1845:       ctx.fillStyle = o.tone > 0.5 ? 'rgba(94,65,40,.3)' : 'rgba(144,104,64,.3)';
1846:       ctx.beginPath(); ctx.arc(0, 0, o.s, 0, TAU); ctx.fill();
1847:     }
1848:     ctx.restore();
1849:   }
1850: }
