1016: function nearestInteractable() {
1017:   if (!state || mode !== 'playing') return null;
1018:   const p = state.player;
1019:   let best = null, bestD = Infinity;
1020: 
1021:   for (const r of world.ruins) {
1022:     for (const n of r.nodes) {
1023:       if (!state.nodes[n.id]) continue;
1024:       const d = dist(p.x, p.y, n.x, n.y);
1025:       if (d < 74 && d < bestD) {
1026:         bestD = d;
1027:         best = {
1028:           kind: 'node', node: n, hold: NODE_HOLDS[n.type],
1029:           label: NODE_NAMES[n.type],
1030:           sub: n.type === 'core' ? 'HOLD TO EXTRACT' : n.type === 'cache' ? 'HOLD TO CRACK SEAL' : 'HOLD TO RECOVER SCRAP'
1031:         };
1032:       }
1033:     }
1034:   }
1035:   for (const n of world.desertScrap) {
1036:     if (!state.nodes[n.id]) continue;
1037:     const d = dist(p.x, p.y, n.x, n.y);
1038:     if (d < 62 && d < bestD) {
1039:       bestD = d;
1040:       best = { kind: 'node', node: n, hold: NODE_HOLDS.scrap, label: 'LONE SALVAGE', sub: 'HOLD TO RECOVER SCRAP' };
1041:     }
1042:   }
1043:   const dMara = dist(p.x, p.y, MARA.x, MARA.y);
1044:   if (dMara < 112 && dMara < bestD) {
1045:     bestD = dMara;
1046:     best = { kind: 'shop', label: "MARA'S STALL", sub: 'TRADE — WATER, RATIONS, UPGRADES' };
1047:   }
1048:   const dRelay = dist(p.x, p.y, RELAY.x, RELAY.y);
1049:   if (dRelay < 105 && dRelay < bestD) {
1050:     const done = state.cores.length >= 3;
1051:     bestD = dRelay;
1052:     best = { kind: 'relay', hold: 3.2, label: done ? 'THE RELAY' : 'RELAY — DORMANT', sub: done ? 'HOLD TO WAKE THE SKY' : `${state.cores.length} / 3 ECHO CORES INSTALLED` };
1053:   }
1054:   return best;
1055: }
