1062:   if (target.kind === 'shop') {
1063:     openShop();
1064:     return;
1065:   }
1066:   if (target.kind === 'relay') {
1067:     if (state.cores.length >= 3) {
1068:       interact.active = true;
1069:       interact.type = 'relay';
1070:       interact.progress = 0;
1071:     } else {
1072:       toast('The relay is dormant. <b>Three echo cores</b> are needed.', 'warn');
1073:     }
1074:     return;
1075:   }
1076:   if (target.kind === 'node') {
1077:     if (target.node.type === 'scrap' && weight() >= capacity()) {
1078:       toast('Your pack is full. Sell salvage at the outpost.', 'warn');
1079:       return;
1080:     }
1081:     interact.active = true;
1082:     interact.type = 'node';
