1094: function completeNode(node) {
1095:   if (node.type === 'scrap') {
1096:     const room = capacity() - weight();
1097:     if (room <= 0) { toast('Your pack is full.', 'warn'); return; }
1098:     const take = Math.min(room, node.amount);
1099:     node.amount -= take;
1100:     state.scrap += take;
1101:     state.stats.scrap += take;
1102:     if (node.amount <= 0) state.nodes[node.id] = false;
1103:     toast(`<b>${take} scrap</b> recovered.${node.amount > 0 ? ' There is more, but no room.' : ''}`, 'good');
1104:     Audio.pickup();
1105:   } else if (node.type === 'cache') {
1106:     state.nodes[node.id] = false;
1107:     const roll = Math.random();
1108:     if (roll < 0.27) {
1109:       state.water = Math.min(100, state.water + 32);
1110:       toast('A sealed water cell. <b>+32 water.</b>', 'good');
1111:     } else if (roll < 0.51) {
1112:       state.food = Math.min(100, state.food + 34);
1113:       toast('Vacuum rations, still good. <b>+34 rations.</b>', 'good');
1114:     } else if (roll < 0.72) {
1115:       state.health = Math.min(100, state.health + 30);
1116:       toast('A med-gel ampoule. <b>+30 body.</b>', 'good');
1117:     } else if (roll < 0.9) {
1118:       state.relics += 1;
1119:       toast('A <b>pre-Leaving relic</b>. Mara will pay well for this.', 'good');
1120:     } else {
1121:       state.credits += 14;
1122:       toast('A tin of old coins. <b>+14 credits.</b>', 'good');
1123:     }
1124:     Audio.pickup();
1125:   } else if (node.type === 'core') {
1126:     state.nodes[node.id] = false;
1127:     if (!state.cores.includes(node.site)) state.cores.push(node.site);
1128:     state.stats.cores = state.cores.length;
1129:     toast('<b>ECHO CORE RECOVERED.</b> The relay can hear it singing.', 'good', 4200);
1130:     Audio.pickup();
1131:     fadeFlash();
1132:     camera.shake = 7;
1133:     const ruin = world.ruins.find(r => r.id === node.site);
1134:     if (ruin) showLocation('ECHO CORE RECOVERED', ruin.name);
1135:   }
1136:   updateObjective();
1137:   updateHUD(true);
1138:   saveGame();
1139: }
