1162: const keys = { w: false, a: false, s: false, d: false, shift: false };
1163: let touchMove = { active: false, x: 0, y: 0 };
1164: let dehydrating = false;
1165: 
1166: function wrapAngle(a) {
1167:   while (a > Math.PI) a -= TAU;
1168:   while (a < -Math.PI) a += TAU;
1169:   return a;
1170: }
1171: 
1172: function isDaytime() { return state.clock >= 5 * 60 + 30 && state.clock < 19 * 60; }
1173: 
1174: function isSheltered() {
1175:   if (!state) return false;
1176:   const p = state.player;
1177:   if (dist(p.x, p.y, OUTPOST.x, OUTPOST.y) < 158) return true;
1178:   for (const r of world.ruins) {
1179:     if (p.x > r.floor.x + 18 && p.x < r.floor.x + r.floor.w - 18 &&
1180:         p.y > r.floor.y + 18 && p.y < r.floor.y + r.floor.h - 18) return true;
1181:   }
1182:   return false;
1183: }
1184: 
1185: function canStand(x, y) {
1186:   const rad = 10;
1187:   for (const r of world.ruins) {
1188:     if (x < r.floor.x - 50 || x > r.floor.x + r.floor.w + 50 || y < r.floor.y - 50 || y > r.floor.y + r.floor.h + 50) continue;
1189:     for (const w of r.walls) {
1190:       const cx = clamp(x, w.x, w.x + w.w);
1191:       const cy = clamp(y, w.y, w.y + w.h);
1192:       if ((x - cx) ** 2 + (y - cy) ** 2 < rad * rad) return false;
1193:     }
1194:     for (const p of r.pillars) {
1195:       if ((x - p.x) ** 2 + (y - p.y) ** 2 < (p.r + rad) ** 2) return false;
1196:     }
1197:   }
1198:   return true;
1199: }
