1201: function movePlayer(dx, dy, dt) {
1202:   const p = state.player;
1203:   const ox = p.x, oy = p.y;
1204:   if (dx) {
1205:     const nx = clamp(p.x + dx, 32, WORLD.w - 32);
1206:     if (canStand(nx, p.y)) p.x = nx;
1207:   }
1208:   if (dy) {
1209:     const ny = clamp(p.y + dy, 32, WORLD.h - 32);
1210:     if (canStand(p.x, ny)) p.y = ny;
1211:   }
1212:   const moved = dist(ox, oy, p.x, p.y);
1213:   if (moved > 0.01) {
1214:     state.stats.distance += moved;
1215:     p.walk += dt * (p.sprint ? 13 : 9);
1216:     footstepTimer -= dt;
1217:     if (footstepTimer <= 0) {
1218:       footstepTimer = p.sprint ? 0.15 : 0.24;
1219:       spawnFootstep();
1220:       if (p.sprint && Math.random() < 0.55) {
1221:         for (let i = 0; i < 2; i++) spawnDust(p.x + (Math.random() - 0.5) * 16, p.y + 8, 1.4);
1222:       }
1223:     }
1224:   }
1225: }
1226: 
1227: function spawnFootstep() {
1228:   if (particles.length > 180) return;
1229:   const p = state.player;
1230:   particles.push({
1231:     x: p.x - Math.cos(p.facing) * 8 + (Math.random() - 0.5) * 5,
1232:     y: p.y - Math.sin(p.facing) * 8 + 6,
1233:     vx: (Math.random() - 0.5) * 4, vy: -1 - Math.random() * 2,
1234:     life: 2.2, max: 2.2, size: 2 + Math.random() * 3, type: 'print', a: p.facing
1235:   });
1236: }
1237: 
1238: function spawnDust(x, y, strength = 1) {
1239:   if (particles.length > 220) return;
1240:   particles.push({
1241:     x, y, vx: (Math.random() - 0.5) * 18 * strength, vy: -4 - Math.random() * 12 * strength,
1242:     life: 0.7 + Math.random() * 0.6, max: 1.3, size: 2 + Math.random() * 6 * strength, type: 'dust'
1243:   });
1244: }
