1246: function updateWeather(dt) {
1247:   const w = state.weather;
1248:   w.timer -= dt;
1249:   if (w.timer <= 0) {
1250:     if (w.type === 'clear') {
1251:       const roll = Math.random();
1252:       if (roll < 0.35) {
1253:         w.type = 'storm'; w.timer = 26 + Math.random() * 18;
1254:         toast('<b>DUST STORM.</b> Find a ruin or the outpost. Do not be caught in the open.', 'warn', 4600);
1255:         camera.shake = 9;
1256:       } else if (roll < 0.82) {
1257:         w.type = 'dust'; w.timer = 38 + Math.random() * 32;
1258:         toast('A dust haze rolls in. The horizon goes soft at the edges.', '', 3200);
1259:       } else {
1260:         w.timer = 48 + Math.random() * 40;
1261:       }
1262:     } else if (w.type === 'dust') {
1263:       if (Math.random() < 0.36) {
1264:         w.type = 'storm'; w.timer = 24 + Math.random() * 18;
1265:         toast('<b>THE HAZE THICKENS.</b> A dust storm is coming down on you.', 'warn', 4000);
1266:         camera.shake = 8;
1267:       } else {
1268:         w.type = 'clear'; w.timer = 70 + Math.random() * 55;
1269:         toast('The air clears. The dunes are exactly where you left them.', '', 2800);
1270:       }
1271:     } else {
1272:       w.type = 'dust'; w.timer = 22 + Math.random() * 20;
1273:       toast('The storm passes. Dust hangs in the air like a held breath.', '', 3000);
1274:     }
1275:   }
1276:   const target = w.type === 'storm' ? 1 : w.type === 'dust' ? 0.45 : 0;
1277:   w.intensity = lerp(w.intensity, target, Math.min(1, dt * 0.8));
1278: }
