1280: function update(dt) {
1281:   if (!state || mode !== 'playing' || paused) return;
1282:   state.elapsed += dt;
1283:   state.player.sprint = keys.shift && (keys.w || keys.a || keys.s || keys.d || touchMove.active);
1284: 
1285:   let dx = 0, dy = 0;
1286:   if (keys.w) dy -= 1;
1287:   if (keys.s) dy += 1;
1288:   if (keys.a) dx -= 1;
1289:   if (keys.d) dx += 1;
1290:   if (touchMove.active) { dx = touchMove.x; dy = touchMove.y; }
1291:   const mag = Math.hypot(dx, dy);
1292:   let moving = mag > 0.08;
1293:   if (mag > 0) {
1294:     dx /= Math.max(1, mag); dy /= Math.max(1, mag);
1295:     if (mag < 0.2) moving = false;
1296:   }
1297:   state.player.moving = moving;
1298:   if (moving) {
1299:     state.player.facing = Math.atan2(dy, dx);
1300:     const sp = speed();
1301:     movePlayer(dx * sp * dt, dy * sp * dt, dt);
1302:     if (state.player.sprint && Math.random() < dt * 8) spawnDust(state.player.x, state.player.y + 7, 0.8);
1303:   }
1304: 
1305:   // Time and exposure
1306:   state.clock += dt * 2.4;
1307:   if (state.clock >= 1440) {
1308:     state.clock -= 1440;
1309:     state.day++;
1310:     toast(`<b>DAY ${state.day}.</b> The wind has changed its mind again.`, '', 3600);
1311:     saveGame();
1312:   }
1313:   const day = isDaytime();
1314:   const sheltered = isSheltered();
1315:   const weather = state.weather.type;
1316:   let waterDrain = 0.038 * (day ? 1.3 : 0.78) * shields();
1317:   if (state.player.sprint && moving) waterDrain += 0.052 * shields();
1318:   if (weather === 'dust') waterDrain += 0.012;
1319:   if (weather === 'storm' && !sheltered) waterDrain += 0.03;
1320:   state.water = Math.max(0, state.water - waterDrain * dt);
1321:   let foodDrain = 0.017 * (state.player.sprint && moving ? 1.35 : 1);
1322:   state.food = Math.max(0, state.food - foodDrain * dt);
1323: 
1324:   if (state.water <= 0) {
1325:     state.health -= 1.35 * dt;
1326:     if (!dehydrating) {
1327:       dehydrating = true;
1328:       toast('<b>DEHYDRATION.</b> Your hands have started to shake. Find water.', 'warn', 4600);
1329:     }
1330:   } else {
1331:     dehydrating = false;
1332:     if (state.water > 55 && state.food > 48 && weather !== 'storm') {
1333:       state.health = Math.min(100, state.health + 0.035 * dt);
1334:     }
1335:   }
1336:   if (state.food <= 0) state.health -= 0.55 * dt;
1337: 
1338:   if (weather === 'storm') {
1339:     if (!sheltered) {
1340:       state.stormExposure += dt;
1341:       if (state.stormExposure > 4) state.health -= 0.48 * dt;
1342:     } else {
1343:       state.stormExposure = Math.max(0, state.stormExposure - dt * 2);
1344:     }
1345:   } else {
1346:     state.stormExposure = Math.max(0, state.stormExposure - dt);
1347:   }
1348: 
1349:   if (state.health <= 0) {
1350:     state.health = 0;
1351:     updateHUD(true);
1352:     gameOver(state.water <= 0 ? 'The canteen ran dry three dunes back. The desert did not notice.' : 'Your body gave out between one ruin and the next. The sand covered the rest.');
1353:     return;
1354:   }
1355: 
1356:   updateWeather(dt);
1357:   Audio.update(dt, state.weather.type, !isDaytime());
1358: 
1359:   if (state.scanCooldown > 0) state.scanCooldown = Math.max(0, state.scanCooldown - dt);
1360:   if (scanFlash > 0) scanFlash = Math.max(0, scanFlash - dt);
1361: 
1362:   // Discovery
1363:   const p = state.player;
1364:   for (const r of world.ruins) {
1365:     if (!state.discovered[r.id] && dist(p.x, p.y, r.x, r.y) < 610) {
1366:       state.discovered[r.id] = true;
1367:       state.stats.ruins = Object.keys(state.discovered).filter(k => !k.startsWith('lm-')).length;
1368:       showLocation(r.kicker, r.name);
1369:       if (!r.core) toast(`<b>${r.name}</b> — discovered.`, '', 2600);
1370:       else if (state.cores.length < 3) toast(`<b>${r.name}</b> — an echo core is here.`, 'good', 3000);
1371:       saveGame();
1372:     }
1373:   }
1374:   for (const lm of LANDMARKS) {
1375:     if (!state.discovered['lm-' + lm.id] && dist(p.x, p.y, lm.x, lm.y) < 520) {
1376:       state.discovered['lm-' + lm.id] = true;
1377:       showLocation(lm.kicker, lm.name);
1378:       toast(lm.flavor, '', 4200);
1379:     }
1380:   }
1381: 
1382:   // Location label
1383:   let loc = '';
