312: function buildRuin(def) {
313:   const rng = mulberry32(def.seed * 997 + 13);
314:   const hw = def.w / 2, hh = def.h / 2, t = 14;
315:   const walls = [];
316:   const addWall = (x, y, w, h) => walls.push({ x: def.x + x, y: def.y + y, w, h });
317:   const addLocal = (x, y, w, h) => addWall(x, y, w, h);
318: 
319:   // Outer shell with collapsed gaps and one broad entrance.
320:   addLocal(-hw, -hh, def.w * 0.61, t);
321:   addLocal(-hw + def.w * 0.72, -hh, def.w * 0.28, t);
322:   addLocal(-hw, hh - t, def.w * 0.42, t);
323:   addLocal(-hw + def.w * 0.59, hh - t, def.w * 0.41, t);
324:   addLocal(-hw, -hh + t, t, def.h * 0.52);
325:   addLocal(-hw, hh * 0.66, t, hh * 0.34 - t);
326:   addLocal(hw - t, -hh + t, t, def.h * 0.31);
327:   addLocal(hw - t, -hh + def.h * 0.44, t, def.h * 0.56 - t);
328: 
329:   // Inner rooms, intentionally incomplete.
330:   addLocal(-def.w * 0.22, -hh + 28, t, def.h * 0.25);
331:   addLocal(-def.w * 0.22, hh * 0.32, t, hh * 0.68 - t - 24);
332:   addLocal(-hw + 28, hh * 0.12, def.w * 0.22, t);
