176: const Audio = {
177:   ctx: null, master: null, windGain: null, windFilter: null, muted: false, started: false,
178:   init() {
179:     if (this.ctx) return;
180:     const AC = window.AudioContext || window.webkitAudioContext;
181:     if (!AC) return;
182:     const ac = this.ctx = new AC();
183:     this.master = ac.createGain();
184:     this.master.gain.value = this.muted ? 0 : 0.55;
185:     this.master.connect(ac.destination);
186: 
187:     const len = ac.sampleRate * 4;
188:     const buffer = ac.createBuffer(1, len, ac.sampleRate);
189:     const data = buffer.getChannelData(0);
190:     let last = 0;
191:     for (let i = 0; i < len; i++) {
192:       const white = Math.random() * 2 - 1;
193:       last = last * 0.985 + white * 0.015;
194:       data[i] = last * 3.2 + white * 0.035;
195:     }
196:     const src = ac.createBufferSource();
197:     src.buffer = buffer; src.loop = true;
198:     this.windFilter = ac.createBiquadFilter();
199:     this.windFilter.type = 'lowpass';
200:     this.windFilter.frequency.value = 420;
201:     this.windFilter.Q.value = 0.7;
202:     this.windGain = ac.createGain();
203:     this.windGain.gain.value = 0.24;
204:     src.connect(this.windFilter).connect(this.windGain).connect(this.master);
205:     src.start();
206: 
207:     // low, breathing drone
208:     const drone = ac.createOscillator();
209:     const drone2 = ac.createOscillator();
210:     const dg = ac.createGain();
211:     drone.type = 'sine'; drone.frequency.value = 55;
212:     drone2.type = 'triangle'; drone2.frequency.value = 82.5;
213:     dg.gain.value = 0.025;
214:     drone.connect(dg); drone2.connect(dg); dg.connect(this.master);
215:     drone.start(); drone2.start();
216:     this.started = true;
217:   },
218:   resume() {
219:     if (!this.ctx) this.init();
220:     if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
221:   },
222:   setMuted(m) {
223:     this.muted = m;
224:     document.body.classList.toggle('muted', m);
225:     if (this.master && this.ctx) {
226:       this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.1);
227:     }
228:   },
229:   blip(freq = 500, dur = 0.06, gain = 0.05, type = 'sine') {
230:     if (!this.ctx || this.muted || this.ctx.state !== 'running') return;
231:     const ac = this.ctx;
232:     const o = ac.createOscillator(), g = ac.createGain();
233:     o.type = type; o.frequency.value = freq;
234:     g.gain.setValueAtTime(0, ac.currentTime);
235:     g.gain.linearRampToValueAtTime(gain, ac.currentTime + 0.006);
236:     g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + dur);
237:     o.connect(g).connect(this.master);
238:     o.start(); o.stop(ac.currentTime + dur + 0.02);
239:   },
240:   scan() {
241:     if (!this.ctx || this.muted) return;
242:     const ac = this.ctx;
243:     const o = ac.createOscillator(), g = ac.createGain();
244:     o.type = 'sine';
245:     o.frequency.setValueAtTime(720, ac.currentTime);
246:     o.frequency.exponentialRampToValueAtTime(180, ac.currentTime + 0.45);
247:     g.gain.setValueAtTime(0.0001, ac.currentTime);
248:     g.gain.exponentialRampToValueAtTime(0.055, ac.currentTime + 0.03);
249:     g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + 0.5);
250:     o.connect(g).connect(this.master); o.start(); o.stop(ac.currentTime + 0.55);
251:   },
252:   pickup() {
253:     if (!this.ctx || this.muted) return;
254:     const ac = this.ctx;
255:     [440, 660, 880].forEach((f, i) => {
256:       const o = ac.createOscillator(), g = ac.createGain();
257:       o.type = 'triangle'; o.frequency.value = f;
258:       g.gain.setValueAtTime(0, ac.currentTime + i * 0.055);
259:       g.gain.linearRampToValueAtTime(0.04, ac.currentTime + i * 0.055 + 0.01);
260:       g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + i * 0.055 + 0.16);
261:       o.connect(g).connect(this.master);
262:       o.start(ac.currentTime + i * 0.055); o.stop(ac.currentTime + i * 0.055 + 0.2);
263:     });
